mod common;use common::*;use somnia_vibespace_storage::*;
#[test]fn all_board_history_is_counted_and_unknown_counts_fail_closed(){let s=mem_store();let (space,studio,run)=setup(&s);let other=s.create_run(&studio.id).unwrap();for r in [&run.id,&other.id]{s.append_event(r,"agent.usage",&serde_json::json!({"inputTokens":3,"outputTokens":4,"cacheReadTokens":900}),None).unwrap();}assert_eq!(s.board_reported_tokens(&space.id).unwrap(),14);s.append_event(&run.id,"agent.usage",&serde_json::json!({"inputTokens":null,"outputTokens":1}),None).unwrap();assert!(s.board_reported_tokens(&space.id).is_err());}
#[test]fn upgrade_from_v6_preserves_spaces_and_defaults_budget_disabled(){let dir=tempfile::tempdir().unwrap();let path=dir.path().join("db");{let mut c=rusqlite::Connection::open(&path).unwrap();somnia_vibespace_storage::schema::migrate(&mut c,&MIGRATIONS[..6]).unwrap();}let store=Store::open(&path,opts_none()).unwrap();let space=store.create_space(NewSpace::personal("kept")).unwrap();assert!(!store.board_budget(&space.id).unwrap().enabled);assert_eq!(store.capabilities().db_schema_version,7);}
